+/** Preserve source loaders for a TypeScript CLI entry without cloning debugger flags. */
+export function childCliArgs(
+  entry: string,
+  cliArgs: string[],
+  execArgv: string[] = process.execArgv,
+): string[] {
+  if (!/\.[cm]?tsx?$/.test(entry)) return [entry, ...cliArgs];
